return ['x-generator'=>'GlotPress/4.1.0','translation-revision-date'=>'2020-10-23 10:29:21+0000','plural-forms'=>'nplurals=1; plural=0;','project-id-version'=>'WordPress - 5.5.x - Administration - Network Admin','language'=>'ms','messages'=>['Confirm'=>'Sahkan','Cannot create an empty user.'=>'Tidak dapat mewujudkan pengguna kosong.','Duplicated username or email address.'=>'Nama pengguna atau alamat emel terduplikasi.','Allow new registrations'=>'Benarkan pendaftaran baharu','Registration notification'=>'Pemberitahuan notifikasi','Add New Users'=>'Tambah Pengguna Baharu','Banned Names'=>'Nama-Nama Yang Dilarang','Limited Email Registrations'=>'Pendaftaran Emel Terhad','Banned Email Domains'=>'Emel Domain yang Dilarang','Welcome Email'=>'Emel Alu-Aluan','Welcome User Email'=>'Emel Alu-Aluan Pengguna','The welcome email sent to new users.'=>'Emel alu-aluan yang dihantar kepada para pengguna baharu.','First Page'=>'Halaman Pertama','First Comment'=>'Komen Pertama','First Comment Author'=>'Pengarang Komen Pertama','First Comment URL'=>'URL Komen Pertama','Max upload file size'=>'Saiz fail muat naik maksima','Default Language'=>'Bahasa Lalai','Add Site'=>'Tambah Laman','Admin Email'=>'Emel Pentadbir','A new user will be created if the above email address is not in the database.'=>'Pengguna baharu akan diwujudkan sekiranya alamat emel di atas tidak terdapat dalam pangkalan data.','[%s] New Site Created'=>'[%s] Laman Baharu Diwujudkan','Network Admin Email'=>'Emel Pentadbir Rangkaian','Send the network admin an email notification every time someone registers a site or user account'=>'Hantar kepada pentadbir rangkaian emel pemberitahuan setiap kali seseorang mendaftar sesuatu laman atau akaun pengguna','Users are not allowed to register these sites. Separate names by spaces.'=>'Pengguna tidak dibenarkan mendaftar laman-laman ini. Pisahkan nama menggunakan ruang.','The welcome email sent to new site owners.'=>'Emel alu-aluan dihantar ke pemilik laman baharu.','Site upload space'=>'Ruang muat naik laman','Next Sites'=>'Laman-Laman Seterusnya','Missing or invalid site address.'=>'Alaman laman hilang atau tidak sah.','Missing email address.'=>'Alamat emel hilang.','Operational Settings'=>'Penetapan Operasi','Registration Settings'=>'Tetapan Pendaftaran','New Site Settings'=>'Tetapan Laman Baharu','Upload Settings'=>'Tetapan Muat Naik','Enable administration menus'=>'Bolehkan menu-menu pentadbiran','Registration is disabled'=>'Pendaftaran telah dilumpuhkan','User accounts may be registered'=>'Akaun pengguna boleh didaftarkan','Logged in users may register new sites'=>'Pengguna yang log masuk boleh mendaftar laman baharu','Both sites and user accounts can be registered'=>'Kedua-dua laman dan akaun pengguna boleh didaftarkan','All done!'=>'Semuanya selesai!','The first post on a new site.'=>'Kiriman pertama pada laman baharu.','The first page on a new site.'=>'Halaman pertama pada laman baharu.','The first comment on a new site.'=>'Komen pertama pada laman baharu.','The author of the first comment on a new site.'=>'Pengarang bagi komen pertama pada laman baharu.','The URL for the first comment on a new site.'=>'URL bagi komen pertama pada laman baharu.','Limit total size of files uploaded to %s MB'=>'Hadkan jumlah saiz fail yang dimuat nauk kepada %s MB','Upload file types'=>'Muat naik jenis fail','There was an error creating the user.'=>'Terdapat ralat mewujudkan pengguna.','Sorry, you are not allowed to change the current site.'=>'Maaf, anda tidak dibenarkan menukar laman semasa.','Sites deleted.'=>'Laman-laman dipadam.','Site deleted.'=>'Laman dipadam.','Site archived.'=>'Laman diarkibkan.','Site unarchived.'=>'Laman dinyaharkibkan.','Site activated.'=>'Laman diaktifkan.','Site deactivated.'=>'Laman dinyahaktifkan.','Users marked as spam.'=>'Para pengguna ditanda sebagai spam.','Users deleted.'=>'Pengguna dipadam.','Sites removed from spam.'=>'Laman-laman yang dikeluarkan dari spam.','Sites marked as spam.'=>'Laman-laman yang ditanda sebagai spam.','Site removed from spam.'=>'Laman dikeluarkan dari spam.','Site marked as spam.'=>'Laman ditanda sebagai spam.','Users removed from spam.'=>'Pengguna dikeluarkan dari spam.','Can&#8217;t create an empty site.'=>'Tidak dapat mewujudkan laman kosong.','If you want to limit site registrations to certain domains. One domain per line.'=>'Jika anda ingin menghadkan pendaftaran laman bagi domain-domain tertentu. Satu domain setiap baris.','If you want to ban domains from site registrations. One domain per line.'=>'Jika anda ingin melarang domain daripada pendaftaran laman. Satu domain setiap baris.','If your browser doesn&#8217;t start loading the next page automatically, click this link:'=>'Jika pelayar anda tidak mula memuatkan halaman seterusnya secara automatik, klik pada link ini:','The following words are reserved for use by WordPress functions and cannot be used as blog names: %s'=>'Perkataan-perkataan berikut adalah dirizabkan bagi kegunaan fungsian WordPress dan tidak boleh digunakan sebagai nama blog: <code>%s</code>','This screen sets and changes options for the network as a whole. The first site is the main site in the network and network options are pulled from that original site&#8217;s options.'=>'Skrin ini menetapkan dan menukar pilihan bagi rangkaian secara keseluruhan. Laman pertama adalah laman utama dalam rangkaian ini dan pilihan rangkaian adalah diambil daripada pilihan laman asal.','Registration settings can disable/enable public signups. If you let others sign up for a site, install spam plugins. Spaces, not commas, should separate names banned as sites for this network.'=>'Tetapan pendaftaran boleh membolehkan/melumpuhkan pendaftaran awam. Jika anda benarkan orang lain mendaftar pada sesuatu laman, pasangkan pemalam spam. Ruang, bukan koma, patut memisahkan nama-nama yang dilarang sebagai laman-laman bagi rangkaian ini.','New site settings are defaults applied when a new site is created in the network. These include welcome email for when a new site or user account is registered, and what&#8127;s put in the first post, page, comment, comment author, and comment URL.'=>'Tetapan laman baharu adalah tetapan lalai yang digunakan apabila suatu laman baharu diwujudkan dalam rangkaian. Ini termasuklah emel alu-aluan apabila laman atau akaun pengguna baharu didaftarkan, dan apa-apa yang diletakkan dalam kiriman, halaman, komen, pengarang komen, dan URL komen yang pertama.','Menu setting enables/disables the plugin menus from appearing for non super admins, so that only super admins, not site admins, have access to activate plugins.'=>'Tetapan menu membolehkan/melumpuhkan menu pemalam daripada muncul bagi bukan pentadbir super, agar hanya pentadbir super, bukan pentadbir laman, mempunyai capaian untuk mengaktifkan pemalam.','This is the main table of all sites on this network. Switch between list and excerpt views by using the icons above the right side of the table.'=>'Ini adalah jadual utama untuk semua laman-laman di rangkaian ini. Alih antara paparan senarai dan petikan menggunakan ikon-ikon di atas sebelah kanan jadual.','This screen enables and disables the inclusion of themes available to choose in the Appearance menu for each site. It does not activate or deactivate which theme a site is currently using.'=>'Skrin ini membolehkan dan melumpuhkan kemasukan tema yang ada untuk dipilih dalam menu Penampilan bagi setiap laman. Ia tidak mengaktifkan atau menyahaktifkan tema yang mana satu sesuatu laman sedang gunakan.','If the network admin disables a theme that is in use, it can still remain selected on that site. If another theme is chosen, the disabled theme will not appear in the site&#8217;s Appearance > Themes screen.'=>'Jika pentadbir rangkaian melumpuhkan tema yang sedang digunakan, ia masih boleh tetap dipilih dalam laman tersebut. Jika tema yang lain dipilih, tema yang dilumpukan tidak akan muncul dalam skrin Penampilan > Tema laman tersebut.','If a version update to core has not happened, clicking this button won&#8217;t affect anything.'=>'Jika versi kemaskini pada teras tidak berlaku, mengklik pada butang ini tidak akan memberi apa-apa kesan.','If this process fails for any reason, users logging in to their sites will force the same update.'=>'Jika proses ini gagal disebabkan apa-apa sebab, para pengguna yang melog masuk dalam laman mereka akan memaksa kemas kini yang sama.','This table shows all users across the network and the sites to which they are assigned.'=>'Jadual ini menunjukkan semua pengguna di keseluruhan rangkaian dan laman-laman dimana mereka ditetapkan.','You can sort the table by clicking on any of the table headings and switch between list and excerpt views by using the icons above the users list.'=>'Anda boleh mengisih jadual dengan mengklik pada mana-mana tajuk jadual dan beralih antara paparan senarai dan petikan dengan menggunakan ikon-ikon di atas senarai pengguna.','Users who are signed up to the network without a site are added as subscribers to the main or primary dashboard site, giving them profile pages to manage their accounts. These users will only see Dashboard and My Sites in the main navigation until a site is created for them.'=>'Pengguna yang mendaftar di rangkaian tanpa laman adalah ditambah sebagai pelanggan kepada laman papan pemuka utama atau primer, memberikan mereka halaman profail untuk mengurus akaun mereka. Para pengguna ini hanya akan melihat Papan Pemuka dan Laman Saya dalam navigasi utama sehingga suatu laman diwujudkan untuk mereka.','You can make an existing user an additional super admin by going to the Edit User profile page and checking the box to grant that privilege.'=>'Anda boleh membuat seseorang pengguna sedia ada sebagai pentadbir super tambahan dengan melawat ke halaman profail Sunting Pengguna dan menanda kota untuk memberi keistimewaan tersebut.','Visit to go to the front-end site live.'=>'Lawat untuk pergi ke bahagian hadapan laman secara langsung.','Upload settings control the size of the uploaded files and the amount of available upload space for each site. You can change the default value for specific sites when you edit a particular site. Allowed file types are also listed (space separated only).'=>'Tetapan muat naik mengawal saiz fail yang dimuat naik dan bilangan ruang muat naik yang ada untuk setiap laman. Anda boleh menukar nilai lalai bagi laman-laman khusus apabila anda menyunting laman berkenaan. Jenis fail yang dibenarkan juga disenaraikan (pisahkan dengan ruang sahaja).','You can also go to the user&#8217;s profile page by clicking on the individual username.'=>'Anda juga boleh melawat ke halaman profail pengguna berkenaan dengan mengklik pada nama pengguna individu.','The bulk action will permanently delete selected users, or mark/unmark those selected as spam. Spam users will have posts removed and will be unable to sign up again with the same email addresses.'=>'Aksi pukal akan memadam para pengguna yang dipilih secara kekal, atau menanda/menyahnanda pilihan sebagai spam. Para pengguna spam akan dikeluarkan kiriman-kiriman mereka dan tidak akan dapat mendaftar semula dengan alamat emel yang sama.','Operational settings has fields for the network&#8217;s name and admin email.'=>'Penetapan operasi mempunyai medan-medan bagi nama rangkaian dan emel pentadbir.','Hovering over each site reveals seven options (three for the primary site):'=>'Melegar pada setiap laman mendedahkan tujuh pilihan (tiga bagi laman utama):','Deactivate, Archive, and Spam which lead to confirmation screens. These actions can be reversed later.'=>'Nyahaktif, Arkib, dan Spam yang membawa kepada skrin pengesahan. Tindakan-tindakan tersebut boleh diterbalikkan kemudian.','The site ID is used internally, and is not shown on the front end of the site or to users/viewers.'=>'ID laman digunakan secara dalaman, dan tidak ditunjukkan di hadapan laman atau kepada pengguna/penonton.','If the admin email for the new site does not exist in the database, a new user will also be created.'=>'Jika emel pentadbir bagi laman baharu berkenaan tidak wujud dalam pangkalan data, pengguna baharu juga akan diwujudkan.','Warning! User cannot be modified. The user %s is a network administrator.'=>'Amaran! Pengguna tidak boleh diubahsuai. Pengguna %s adalah pentadbir rangkaian.','The Network creation panel is not for WordPress MU networks.'=>'Panel pewujudan Rangkaian bukanlah untuk rangkaian-rangkaian WordPress MU.','Create a Network of WordPress Sites'=>'Wujudkan Rangkaian Laman WordPress','This screen allows you to configure a network as having subdomains (<code>site1.example.com</code>) or subdirectories (<code>example.com/site1</code>). Subdomains require wildcard subdomains to be enabled in Apache and DNS records, if your host allows it.'=>'Skrin ini membenarkan anda menetapkan rangkaian agar mempunyai sub-domain (<code>site1.example.com</code>) atau or sub-direktori (<code>example.com/site1</code>). Sub-domain memerlukan sub-domain kad liar dibolehkan dalam rekod-rekod Apache dan DNS, jika hos anda membenarkannya.','Choose subdomains or subdirectories; this can only be switched afterwards by reconfiguring your installation. Fill out the network details, and click Install. If this does not work, you may have to add a wildcard DNS record (for subdomains) or change to another setting in Permalinks (for subdirectories).'=>'Pilih sub-domain atau sub-direktori; ini hanya boleh ditukar kemudian dengan menetapkan semula pemasangan anda. Isikan keterangan rangkaian, dan klik Pasang. Jika ini tidak berfungsi, anda mungkin perlu menambah rekod kad liar DNS (bagi sub-domain) atau menukar kepada tetapan yang lain dalam Pautan Kekal (bagi sub-direktori).','The next screen for Network Setup will give you individually-generated lines of code to add to your wp-config.php and .htaccess files. Make sure the settings of your FTP client make files starting with a dot visible, so that you can find .htaccess; you may have to create this file if it really is not there. Make backup copies of those two files.'=>'Skrin seterusnya bagi Pemasangan Rangkaian akan memberikan anda barisan kod yang dijanakan secara individu untuk fail-fail wp-config.php dan .htaccess anda. Pastikan tetapan bagi klien FTP anda dibuat supaya fail-fail yang bermula dengan titk noktah adalah kelihatan, supaya anda dapat mencari .htacces; anda mungkin perlu mewujudkan fail ini sekiranya ia betul-betul tidak wujud. Buat salinan sandaran bagi kedua-dua fail berkenaan.','Once you add this code and refresh your browser, multisite should be enabled. This screen, now in the Network Admin navigation menu, will keep an archive of the added code. You can toggle between Network Admin and Site Admin by clicking on the Network Admin or an individual site name under the My Sites dropdown in the Toolbar.'=>'Sesusah anda menambah kod ini dan menyegar semula pelayar anda, multi-laman sepatutnya dibolehkan. Skrin ini, kini dalam menu mavigasi Pentadbir Rangkaian, akan menyimpan arkib kod yang ditambah. Anda boleh togol antara Pentadbir Rangkaian dan Pentadbir Laman dengan mengklik pada Pentadbir Rangkaian atau nama laman individu di bawah jatuh turun Laman Saya dalam Bar Alatan.','The choice of subdirectory sites is disabled if this setup is more than a month old because of permalink problems with &#8220;/blog/&#8221; from the main site. This disabling will be addressed in a future version.'=>'Pilihan laman-laman sub-direktori dinyahbolehkan jika penetapan berkenaan adalah melebihi sebulan oleh kerana masalah pautan kekal dengan &#8220;/blog/&#8221; daripada laman utama. Penyahbolehan ini akan ditujukan dalam versi akan datang.','Network'=>'Rangkaian','Please <a href="%s">deactivate your plugins</a> before enabling the Network feature.'=>'Sila <a href="%s">nyahaktifkan pemalam anda</a> sebelum membolehkan ciri-ciri Rangkaian.','Once the network is created, you may reactivate your plugins.'=>'Sesudah rangkaian diwujudkan, anda boleh membolehkan kembali pemalam anda.','You cannot install a network of sites with your server address.'=>'Anda tidak boleh memasang rangkaian laman dengan alaman pelayan anda.','Return to Dashboard'=>'Kembali ke Papan Pemuka','Error: The network could not be created.'=>'Ralat: Rangkaian tidak dapat diwujudkan.','Welcome to the Network installation process!'=>'Selamat datang ke proses Pemasangan Rangkaian!','Fill in the information below and you&#8217;ll be on your way to creating a network of WordPress sites. We will create configuration files in the next step.'=>'Isikan maklumat di bawah dan anda akan dapat meneruskan pengwujudan rangkaian laman WordPress. Kami akan mencipta fail-fail konfigurasi dalam langkah-langkah seterusnya.','Note:'=>'Nota:','Addresses of Sites in your Network'=>'Alamat Laman dalam Rangkaian anda','You will need a wildcard DNS record if you are going to use the virtual host (sub-domain) functionality.'=>'Anda akan memerlukan rekod DNS kad liar jika anda menggunakan fungsian hos virtual (sub-domain).','Sub-domains'=>'Sub-domain','subdomain exampleslike <code>site1.%1$s</code> and <code>site2.%1$s</code>'=>'seperti <code>site1.%1$s</code> dan <code>site2.%1$s</code>','Sub-directories'=>'Sub-direktori','subdirectory exampleslike <code>%1$s/site1</code> and <code>%1$s/site2</code>'=>'seperti <code>%1$s/site1</code> dan <code>%1$s/site2</code>','Server Address'=>'Alamat Pelayan','Network Details'=>'Perincian Rangkaian','The main site in a sub-directory installation will need to use a modified permalink structure, potentially breaking existing links.'=>'Laman utama dalam pemasangan sub-direktori akan memerlukan pengubahsuaian struktur pautan kekal, dan mungkin akan merosakkan pautan-pautan semasa.','Because your installation is in a directory, the sites in your WordPress network must use sub-directories.'=>'Oleh kerana pemasangan anda adalah dalam direktori, maka laman-laman dalam rangkaian WordPress anda mesti menggunakan sub-direktori.','Because your installation is not new, the sites in your WordPress network must use sub-domains.'=>'Oleh kerana pemasangan anda bukan baharu, maka laman-laman dalam rangkaian WordPress anda mestilah menggunakan sub-domain.','Network Title'=>'Tajuk Rangkaian','What would you like to call your network?'=>'Apakah gelaran rangkaian anda?','Your email address.'=>'Alamat emel anda.','The original configuration steps are shown here for reference.'=>'Langkah-langkah konfigurasi asal ditunjukkan di sini untuk rujukan.','An existing WordPress network was detected.'=>'Rangkaian WordPress semasa telah dikesan.','Please complete the configuration steps. To create a new network, you will need to empty or remove the network database tables.'=>'Sila lengkapkan langkah-langkah konfigurasi berkenaan. Untuk mewujudkan rangkaian baharu, anda perlu mengosongkan atau membuang jadual-jadual pangkalan data rangkaian.','Enabling the Network'=>'Bolehkan Rangkaian','Complete the following steps to enable the features for creating a network of sites.'=>'Selesaikan langkah-langkah berikut untuk membolehkan ciri-ciri bagi mewujudkan rangkaian laman.','To make your installation more secure, you should also add:'=>'Untuk membuat pemasangan lebih selamat, anda patut juga menambah:','Once you complete these steps, your network is enabled and configured. You will have to log in again.'=>'Sebaik sahaja anda menyelesaikan langkah-langkah berkenaan, rangkaian anda dibolehkan dan dikonfigurasikan. Anda perlu long masuk sekali lagi.','All Sites'=>'Semua Laman','Themes %s'=>'Tema %s','Installed Themes'=>'Tema Yang Dipasang','Network Settings'=>'Tetapan Rangkaian','Updates'=>'Kemaskini','Add User will set up a new user account on the network and send that person an email with username and password.'=>'Tambah Pengguna akan menetapkan akaun pengguna baharu pada rangkaian dan menghantar emel yang mengandungi nama pengguna dan kata laluan kepada orang tersebut.','Cannot add user.'=>'Tidak dapat menambah pengguna.','Add User'=>'Tambah Pengguna','Add New takes you to the Add New Site screen. You can search for a site by Name, ID number, or IP address. Screen Options allows you to choose how many sites to display on one page.'=>'Tambah Baharu membawa anda ke skirn Tambah Laman Baharu. Anda boleh mencari laman menggunakan Nama, nombor ID, atau alamat IP. Pilihan Skrin memboleh anda memilih bilangan laman untuk dipaparkan dalam satu mukasurat.','An Edit link to a separate Edit Site screen.'=>'Pautan Sunting ke skrin Sunting Laman yang berasingan.','Dashboard leads to the Dashboard for that site.'=>'Papan pemuka membawa kepada Papan Pemuka bagi laman tersebut.','Delete which is a permanent action after the confirmation screens.'=>'Padam iaitu tindakan kekal selepas skrin pengesahan.','Clicking on bold headings can re-sort this table.'=>'Mengklik pada tajuk yang dihitamkan boleh menyusun semula jadual ini.','Sorry, you are not allowed to delete the site %s.'=>'Maaf, anda tidak dibenarkan menghapus laman %s.','Invalid site ID.'=>'ID laman tidak sah.','Edit Site: %s'=>'Sunting Laman: %s','Theme enabled.'=>'Tema %s dibolehkan.','Theme disabled.'=>'Tema %s dinyahbolehkan.','No theme selected.'=>'Tiada tema dipilih.','Network enabled themes are not shown on this screen.'=>'Tema yang dibolehkan rangkaian tidak ditunjukkan di skrin ini.','Delete Theme'=>'Padam Tema','This theme may be active on other sites in the network.'=>'Tema berkenaan mungkin masih aktif di laman-laman lain dalam rangkaian ini.','You are about to remove the following theme:'=>'Anda akan mengeluarkan tema berikut:','Are you sure you want to delete these themes?'=>'Anda pasti anda ingin hapuskan tema-tema ini?','Yes, delete this theme'=>'Ya, hapuskan tema berkenaan','No, return me to the theme list'=>'Tidak, kembalikan saya ke senarai tema','Themes can be enabled on a site by site basis by the network admin on the Edit Site screen (which has a Themes tab); get there via the Edit action link on the All Sites screen. Only network admins are able to install or edit themes.'=>'Tema boleh dibolehkan atas dasar laman demi laman oleh pentadbir rangkaian di skrin Sunting Laman (yang mempunyai tab Tema); dapatkannya melalui pautan tindakan Sunting di skrin Semua Laman. Hanya para pentadbir rangkaian yang boleh memasang atau menyunting tema.','You cannot delete a theme while it is active on the main site.'=>'Anda tidak boleh memadam tema semasa ianya aktif di laman utama.','Site info updated.'=>'Maklumat laman dikemaskini.','This screen is for Super Admins to add new sites to the network. This is not affected by the registration settings.'=>'Skrin ini adalah bagi para Pentadbir Super untuk menambah laman baharu ke rangkaian. Ini tidak dijejaskan oleh tetapan pendaftaran.','Site added. <a href="%1$s">Visit Dashboard</a> or <a href="%2$s">Edit Site</a>'=>'Laman ditambah. <a href="%1$s">Lawat Papan Pemuka</a> atau <a href="%2$s">Sunting Laman</a>','Add New Site'=>'Tambah Laman Baharu','Site options updated.'=>'Pilihan laman dikemaskini.','User is already a member of this site.'=>'Pengguna sudahpun menjadi ahli laman ini.','Enter the username of an existing user.'=>'Masukkan nama pengguna bagi pengguna sedia ada.','Select a user to change role.'=>'Pilih pengguna untuk ditukar peranan.','Select a user to remove.'=>'Pilih pengguna untuk dikeluarkan.','User created.'=>'Pengguna diwujudkan.','Enter the username and email.'=>'Masukkan nama pengguna dan emel.','Super admins can no longer be added on the Options screen. You must now go to the list of existing users on Network Admin > Users and click on Username or the Edit action link below that name. This goes to an Edit User page where you can check a box to grant super admin privileges.'=>'Pentadbir super tidak boleh lagi ditambah pada skrin Opsyen/Piliha. Anda kini mesti pergi ke senarai pengguna sedia ada di Pentadbir Rangkaian > Pengguna dan klik pada pautan tindakan Nama Pengguna atau Sunting di bawah nama berkenaan. Ini membawa anda ke halaman Sunting Pengguna dimana anda boleh memeriksa kotak untuk memberikan keistimewaan pentadbir super.','Allow site administrators to add new users to their site via the "Users &rarr; Add New" page'=>'Benarkan pentadbir laman menambah pengguna baharu ke laman mereka melalui halaman "Pengguna &rarr; Tambah Baharu"','Language Settings'=>'Tetapan Bahasa','Add the designated lines of code to wp-config.php (just before <code>/*...stop editing...*/</code>) and <code>.htaccess</code> (replacing the existing WordPress rules).'=>'Tambah barisan kod ke wp-config.php (betul-betul sebelum <code>/*...stop editing...*/</code>) dan <code>.htaccess</code> (menggantikan peraturan WordPress terdahulu).','Subdirectory networks may not be fully compatible with custom wp-content directories.'=>'Rangkaian sub-direktori mungkin tidak serasi dengan direktori wp-content tersuai.','New site created by %1$s

Address: %2$s
Name: %3$s'=>'Laman baharu diwujudkan oleh %1$s

Alamat: %2$s
Nama: %3$s','Upgrade Network'=>'Tatar Rangkaian','Only use this screen once you have updated to a new version of WordPress through Updates/Available Updates (via the Network Administration navigation menu or the Toolbar). Clicking the Upgrade Network button will step through each site in the network, five at a time, and make sure any database updates are applied.'=>'Hanya gunakan skrin ini apabila anda telah mengemaskini ke versi WordPress baharu melalui Kemaskini/Kemaskini Yang Tersedia (melalui menu navigasi Pentadbiran Rangkaian atau Bar Alatan). Mengklik pada butang Tatar Rangkaian akan membawa anda melalui setiap laman dalam rangkaian, lima pada satu masa, dan memastikan apa-apa pengemaskinian pangkalan data dikenakan.','WordPress has been updated! Before we send you on your way, we need to individually upgrade the sites in your network.'=>'WordPress telah dikemaskini! Sebelum anda teruskan, kami perlu menatar laman-laman dalam rangkaian anda secara individu.','Welcome to your Network Admin. This area of the Administration Screens is used for managing all aspects of your Multisite Network.'=>'Selamat datang ke Pentadbir Rangkaian anda. Kawasan Skrin Pentadbiran ini digunakan bagi mengurus segala aspek Rangkaian Multi Laman anda.','From here you can:'=>'Dari sini anda boleh:','Add and manage sites or users'=>'Tambah dan urus laman atau pengguna','Install and activate themes or plugins'=>'Pasang dan aktifkan tema atau pemalam','Update your network'=>'Kemaskini rangkaian anda','Modify global network settings'=>'Ubah suai tetapan global rangkaian','The Right Now widget on this screen provides current user and site counts on your network.'=>'Wijet Masa Ini pada skirin ini menyediakan kiraan pengguna dan laman semasa di rangkaian anda.','To search for a user or site, use the search boxes.'=>'Untuk mencari pengguna atau laman, gunakan kekotak carian.','Quick Tasks'=>'Tugas-Tugas Pantas','To add a new user, <strong>click Create a New User</strong>.'=>'Untuk menambah pengguna baharu, <strong>klik Wujudkan Pengguna Baharu</strong>.','To add a new site, <strong>click Create a New Site</strong>.'=>'Untuk menambah laman baharu, <strong>klik Wujudkan Laman Baharu</strong>.','To search for a user, <strong>enter an email address or username</strong>. Use a wildcard to search for a partial username, such as user&#42;.'=>'Untuk mencari seseorang pengguna, <strong>masukkan alamat emel atau nama pengguna</strong>. Gunakan carian kad liar bagi nama pengguna separa, seperti pengguna&#42;.','To search for a site, <strong>enter the path or domain</strong>.'=>'Untuk carian bagi sesuatu laman, <strong>masukkan laluan atau domain</strong>.','Hover over any user on the list to make the edit links appear. The Edit link on the left will take you to their Edit User profile page; the Edit link on the right by any site name goes to an Edit Site screen for that site.'=>'Legar pada mana-mana pengguna di senarai agar pautan suntingan kelihatan. Pautan Sunting di sebelah kiri akan membawa anda ke laman profail Sunting Pengguna bagi para pengguna tersebut; pautan Sunting di sebelah kanan bagi apa-apa nama laman akan pergi ke skrin Sunting Laman bagi laman tersebut.','Confirm your action'=>'Sahkan tindakan anda','Add the following to your %1$s file in %2$s, <strong>replacing</strong> other WordPress rules:'=>'Tambah perkara berikut ke fail %1$s anda dalam %2$s, <strong>menggantikan</strong> lain-lain peraturan WordPress:','New registrations settings'=>'Tetapan pendaftaran baharu','Allowed file types. Separate types by spaces.'=>'Jenis fail yang dibenarkan. Pisahkan jenis dengan ruang.','Size in kilobytes'=>'Saiz dalam kilobait','Enable menus'=>'Bolehkan menu','Set site attributes'=>'Tetapkan sifat laman','Delete Themes'=>'Hapus Tema','These themes may be active on other sites in the network.'=>'Tema ini mungkin aktif di laman lain dalam rangkaian.','You are about to remove the following themes:'=>'Anda akan membuang tema berikut:','Yes, delete these themes'=>'Ya, hapuskan tema berkenaan','%s theme enabled.'=>'%s tema dibolehkan.','%s theme disabled.'=>'Tema %s tidak dibolehkan.','%s theme deleted.'=>'%s tema dihapuskan.','Warning! Problem updating %1$s. Your server may not be able to connect to sites running on it. Error message: %2$s'=>'Amaran! Masalah mengemas kini %1$s. Pelayan adan mungkin tidak dihubungi ke laman yang dijanakan olehnya. Mesej ralat: %2$s','<a href="https://codex.wordpress.org/Network_Admin_Settings_Screen">Documentation on Network Settings</a>'=>'<a href="https://codex.wordpress.org/Network_Admin_Settings_Screen">Pendokumenan berkenaan Penetapan Rangkaian</a>','<a href="https://codex.wordpress.org/Network_Admin_Themes_Screen">Documentation on Network Themes</a>'=>'<a href="https://codex.wordpress.org/Network_Admin_Themes_Screen">Pendokumenan berkenaan Tema Rangkaian</a>','<a href="https://codex.wordpress.org/Network_Admin_Users_Screen">Documentation on Network Users</a>'=>'<a href="https://codex.wordpress.org/Network_Admin_Users_Screen">Pendokumenan berkenaan Pengguna Rangkaian</a>','The requested site does not exist.'=>'Laman yang dipohon tidak wujud.','You are about to activate the site %s.'=>'Anda akan mengaktifkan laman %s','You are about to deactivate the site %s.'=>'Anda akan menyahaktifkan laman %s','You are about to unarchive the site %s.'=>'Anda akan menyah-arkibkan laman %s.','You are about to archive the site %s.'=>'Anda akan mengarkib laman %s.','You are about to unspam the site %s.'=>'Anda akan menyah-spam laman %s.','You are about to mark the site %s as spam.'=>'Anda akan menanda laman %s sebagai spam.','You are about to delete the site %s.'=>'Anda akan menghapus laman %s.','You are about to mark the site %s as mature.'=>'Anda akan menanda laman %s sebagai matang.','You are about to mark the site %s as not mature.'=>'Anda akan menanda laman %s sebagai bukan matang.','The requested action is not valid.'=>'Aksi yang dipohon adalah tidak sah.','The domain or path entered conflicts with an existing username.'=>'Domain atau laluan yang dimasukkan bercanggah dengan nama pengguna sedia ada.','Filter site themes list'=>'Tapis senarai tema laman','Site themes list navigation'=>'Navigasi senarai tema laman','Site themes list'=>'Senarai tema laman','Filter site users list'=>'Tapis senarai pengguna laman','Site users list navigation'=>'Navigasi senarai pengguna laman','Site users list'=>'Senarai pengguna laman','Sites list navigation'=>'Navigasi senarai laman','Sites list'=>'Senarai laman','Themes list navigation'=>'Navigasi senarai tema','You must define the %1$s constant as true in your %2$s file to allow creation of a Network.'=>'Anda mesti menentukan pemalar %1$s sebagai benar dalam fail %2$s anda untuk membenarkan pengwujudan Rangkaian.','If registration is disabled, please set %1$s in %2$s to a URL you will redirect visitors to if they visit a non-existent site.'=>'Jika pendaftaran tidak diaktifkan, sila tetapkan %1$s dalam %2$s kepada URL dimana pelawat anda akan dialih sekiranya mereka melawat laman yang tidak wujud.','A password reset link will be sent to the user via email.'=>'Pautan set semula kata laluan akan dihantar kepada pengguna melalui emel.','Archived'=>'Diarkibkan','siteSpam'=>'Spam','Deleted'=>'Dihapuskan','Mature'=>'Matang','No sites found.'=>'Tiada laman dijumpai.','siteMark as spam'=>'Tanda sebagai spam','siteNot Spam'=>'Bukan Spam','Last Updated'=>'Terakhir Dikemaskini','siteRegistered'=>'Berdaftar','%1$s &#8211; %2$s'=>'%1$s &#8211; %2$s','Never'=>'Jangan sesekali','Unarchive'=>'Nyah-arkib','verb; siteArchive'=>'Arkib','No themes found.'=>'Tiada tema dijumpai.','Theme'=>'Tema','themesAll <span class="count">(%s)</span>'=>'Semua <span class="count">(%s)</span>','themesEnabled <span class="count">(%s)</span>'=>'Dibolehkan <span class="count">(%s)</span>','themesDisabled <span class="count">(%s)</span>'=>'Dilumpuhkan <span class="count">(%s)</span>','themesBroken <span class="count">(%s)</span>'=>'Rosak <span class="count">(%s)</span>','Enable'=>'Bolehkan','Disable'=>'Nyahboleh','Network Disable'=>'Rangkaian Dilumpuhkan','Enable %s'=>'Mengaktifkan %s','Network Enable %s'=>'Mengaktifkan Rangkaian %s','Disable %s'=>'Melumpuhkan %s','Network Disable %s'=>'Melumpuhkan Melumpuhkan %s','Broken Theme:'=>'Tema Rosak:','Visit %s homepage'=>'Lawati %s laman utama','Visit Theme Site'=>'Lawat Laman Tema','userMark as spam'=>'Tanda sebagai spam','userNot spam'=>'Bukan spam','Super Admin <span class="count">(%s)</span>'=>'Pentadbir Super <span class="count">(%s)</span>','userRegistered'=>'Berdaftar','You cannot use port numbers such as %s.'=>'Anda tidak boleh menggunakan port nombor seperti %s.','Please make sure the Apache %s module is installed as it will be used at the end of this installation.'=>'Pastikan modul %s Apache telah dipasang, disebabkan ianya akan digunakan pada akhir pemasangan ini.','It looks like the Apache %s module is not installed.'=>'Nampaknya seperti module %s tidak dipasang.','If %1$s is disabled, ask your administrator to enable that module, or look at the <a href="%2$s">Apache documentation</a> or <a href="%3$s">elsewhere</a> for help setting it up.'=>'Jika %1$s tidak diaktifkan, minta pentadbir anda untuk membolehkan modul tersebut, atau lihat pada <a href="%2$s">dokumentasi Apache</a> atau <a href="%3$s">lain-lain</a> bagi bantuan pemasangan.','Please choose whether you would like sites in your WordPress network to use sub-domains or sub-directories.'=>'Sila pilih sama ada anda inginkan laman-laman di rangkaian WordPress anda menggunakan sub-domain atau sub-direktori.','You cannot change this later.'=>'Anda tidak boleh mengubahnya kemudian.','We recommend you change your site domain to %1$s before enabling the network feature. It will still be possible to visit your site using the %3$s prefix with an address like %2$s but any links will not have the %3$s prefix.'=>'Anda disyorkan supaya menukar domain laman anda kepada %1$s sebelum mengaktifkan ciri-ciri rangkaian. Anda masih boleh melawat laman anda menggunakan prefiks %3$s dengan alamat seperti %2$s tetapi apa-apa pautan tidak akan mempunyai prefiks %3$s.','The internet address of your network will be %s.'=>'Alamat Internet untuk rangkaian anda akan ditetapkan sebagai %s.','Because you are using %1$s, the sites in your WordPress network must use sub-directories. Consider using %2$s if you wish to use sub-domains.'=>'Oleh kerana anda menggunakan %1$s, laman-laman dalam rangkaian WordPress and mesti menggunakan sub-direktori. Sila pertimbangkan penggunaan %2$s jika anda ingin menggunakan sub-domain.','We recommend you back up your existing %1$s and %2$s files.'=>'Kami mencadangkan anda membuat salinan sandaran kepada fail-fail %1$s dan %2$s yang sedia ada.','We recommend you back up your existing %s file.'=>'Kami mencadangkan anda membuat salinan sandaran kepada fail-fail %s yang sedia ada.','This unique authentication key is also missing from your %s file.'=>'Kunci pengesahan unik ini juga tidak terdapat dalam fail %s anda.','These unique authentication keys are also missing from your %s file.'=>'Kunci pengesahan unik ini juga tidak terdapat dalam fail %s anda.','email "From" fieldSite Admin'=>'Laman Pentadbir','Only lowercase letters (a-z), numbers, and hyphens are allowed.'=>'Hanya abjad-abjad kecil (a-z), nombor-nombor, dan sempang dibenarkan.','theme%1$s by %2$s'=>'%1$s oleh %2$s','Add the following to your %1$s file in %2$s <strong>above</strong> the line reading %3$s:'=>'Tambah perkara berikut ke fail %1$s anda dalam %2$s <strong>di atas</strong> baris yang berbunyi %3$s:','That&#8217;s all, stop editing! Happy publishing.'=>'Itu sahaja, berhenti menyunting! Selamat menerbit.','First Comment Email'=>'Emel Ulasan Pertama','The email address of the first comment author on a new site.'=>'Alamat emel pengarang ulasan pertama pada laman baharu.','Sorry, you are not allowed to edit this site.'=>'Maaf, anda tidak dibenarkan menyunting laman ini.','Sorry, you are not allowed to add sites to this network.'=>'Maaf, anda tidak dibenarkan menambah laman ke rangkaian ini.','Sorry, you are not allowed to manage themes for this site.'=>'Maaf, anda tidak dibenarkan mengurus tema bagi laman ini.','Sorry, you are not allowed to delete that site.'=>'Maaf, anda tidak dibenarkan menghapus laman berkenaan.','Sorry, you are not allowed to manage network themes.'=>'Maaf, anda tidak dibenarkan mengurus tema rangkaian.','Sorry, you are not allowed to delete themes for this site.'=>'Maaf, anda tidak dibenarkan menghapus tema bagi laman ini.','themeDelete %s'=>'Hapus %s','%s Sites'=>'%s Laman','%s KB'=>'%s KB','Attributes'=>'Sifat','Active Child Theme'=>'Tema Anak Aktif','Sub-directory Installation'=>'Pemasangan Sub-direktori','Sub-domain Installation'=>'Pemasangan sub-domain','There is a pending change of the network admin email to %s.'=>'Terdapat perubahan pada emel pentadbir rangkaian ke %s yang belum selesai.','The username and a link to set the password will be mailed to this email address.'=>'Nama pengguna dan pautan untuk menetapkan kata laluan akan dihantar ke alamat emel ini.','User could not be added to this site.'=>'Pengguna tidak dapat ditambah ke laman ini.','You are about to delete the following sites:'=>'Anda akan menghapuskan laman-laman berikut:','The constant %s cannot be defined when creating a network.'=>'Pemalar %s tidak dapat ditentukan apabila mencipta rangkaian.','<a href="https://wordpress.org/support/article/create-a-network/">Documentation on Creating a Network</a>'=>'<a href="https://wordpress.org/support/article/create-a-network/">Pendokumenan berkenaan Mewujudkan Rangkaian</a>','<a href="https://wordpress.org/support/article/tools-network-screen/">Documentation on the Network Screen</a>'=>'<a href="https://wordpress.org/support/article/tools-network-screen/">Pendokumenan berkenaan Skrin Rangkaian</a>','Main'=>'Utama','themesUpdate Available <span class="count">(%s)</span>'=>'Kemas Kini Tersedia <span class="count">(%s)</span>','<a href="https://wordpress.org/support/article/network-admin/">Documentation on the Network Admin</a>'=>'<a href="https://wordpress.org/support/article/network-admin/">Pendokumenan berkenaan Pentadbir Rangkaian</a>','<a href="https://wordpress.org/support/article/network-admin-updates-screen/">Documentation on Upgrade Network</a>'=>'<a href="https://wordpress.org/support/article/network-admin-updates-screen/">Pendokumenan berkenaan Naik Taraf Rangkaian</a>','sitesAll <span class="count">(%s)</span>'=>'Semua <span class="count">(%s)</span>','Public <span class="count">(%s)</span>'=>'Umum <span class="count">(%s)</span>','Archived <span class="count">(%s)</span>'=>'Arkib <span class="count">(%s)</span>','Mature <span class="count">(%s)</span>'=>'Matang <span class="count">(%s)</span>','sitesSpam <span class="count">(%s)</span>'=>'Spam <span class="count">(%s)</span>','Deleted <span class="count">(%s)</span>'=>'Dihapuskan <span class="count">(%s)</span>','It seems your network is running with Nginx web server. <a href="%s">Learn more about further configuration</a>.'=>'Nampaknya rangkaian anda dijalankan menggunakan pelayan web Nginx web server. <a href="%s">Pelajari dengan lanjut berkenaan tetapan seterusnya</a>.','https://wordpress.org/support/article/nginx/'=>'https://wordpress.org/support/article/nginx/','Y/m/d g:i:s a'=>'Y/m/d g:i:s a','No themes are currently available.'=>'Tiada tema yang tersedia buat masa ini.','Sorry, you are not allowed to change themes automatic update settings.'=>'Maaf, anda tidak dibenarkan menukar tetapan kemas kini automatik untuk tema.','%s theme will be auto-updated.'=>'%s tema akan dikemas kini secara automatik.','%s theme will no longer be auto-updated.'=>'%s tema tidak lagi akan dikemas kini secara automatik.','siteNot spam'=>'Bukan spam']];